export interface ConnectorConfig {
  /** Slack Bot User OAuth Token (xoxb-...). Must have chat:write scope. */
  slackBotToken: string
  /** Slack channel ID (e.g., C1234567890) or name (e.g., #general). */
  slackChannel: string
  /** Injected fetch for testing; defaults to global fetch. */
  fetch?: typeof fetch
}

export interface CalendlyInviteePayload {
  event: string
  created_at: string
  created_by: string
  payload: {
    uri: string
    email: string
    name: string
    status: string
    timezone: string
    event: string
    created_at: string
    updated_at: string
    cancel_url: string
    reschedule_url: string
    questions_and_answers: Array<{
      question: string
      answer: string
      position: number
    }>
    tracking?: Record<string, string>
  }
}

export interface HandleResult {
  ok: true
  channel: string
  ts: string
  message: {
    type: string
    user: string
    text: string
    bot_id: string
  }
}

function formatAnswers(answers: CalendlyInviteePayload['payload']['questions_and_answers']): string {
  if (!answers || answers.length === 0) return 'None'
  return answers
    .sort((a, b) => a.position - b.position)
    .map((qa) => `- ${qa.question}: ${qa.answer}`)
    .join('\n')
}

function buildMessageText(payload: CalendlyInviteePayload['payload']): string {
  const answersText = formatAnswers(payload.questions_and_answers)
  return [
    'New Calendly meeting booked!',
    `Name: ${payload.name}`,
    `Email: ${payload.email}`,
    'Answers:',
    answersText,
  ].join('\n')
}

export async function handle(
  payload: CalendlyInviteePayload,
  config: ConnectorConfig,
): Promise<HandleResult> {
  const fetchImpl = config.fetch ?? fetch

  // Validate required fields
  if (!payload.payload?.name) {
    throw new Error('Missing required field: payload.name')
  }
  if (!payload.payload?.email) {
    throw new Error('Missing required field: payload.email')
  }

  const text = buildMessageText(payload.payload)

  const body = JSON.stringify({
    channel: config.slackChannel,
    text,
  })

  const response = await fetchImpl('https://slack.com/api/chat.postMessage', {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${config.slackBotToken}`,
      'Content-Type': 'application/json',
    },
    body,
  })

  if (!response.ok) {
    throw new Error(
      `Slack API error: ${response.status} ${response.statusText} for POST https://slack.com/api/chat.postMessage`,
    )
  }

  const result = (await response.json()) as HandleResult
  return result
}

import { describe, it, expect, vi } from 'vitest'
