import {
  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  RecordedCall,
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      slackBotToken: 'xoxb-test-token',
      slackChannel: 'C1234567890',
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as CalendlyInviteePayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.ok).toBe(true)
    expect(result.channel).toBe('C1234567890')
  })
})

